import java.util.Scanner;

public class Main {
    static int Mod;
    static int n, k;
    static long[] fact;
    static long[] inv_fact;
    static long[] inv;
    static long[][] cache;

    static long fastExponentiation(int base, int exponent) {
        long result = 1;
        long current = base;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * current) % Mod;
            }
            current = (current * current) % Mod;
            exponent >>= 1;
        }
        return result;
    }

    static long recursiveSolve(int used, int subset) {
        if (cache[used][subset] != -1) return cache[used][subset];
        long answer = 0;
        if (subset == 0) {
            answer = fact[n];
            for (int i = 1; i <= used; ++i)
                answer = (answer * (k - i + 1)) % Mod;
            return cache[used][subset] = answer;
        }
        if (used > k) return 0;
        int lowest_bit = subset & (-subset);
        int remaining = subset - lowest_bit;
        for (int T = remaining; ; T = (T - 1) & remaining) {
            answer = (answer + inv_fact[subset - T] * recursiveSolve(used + 1, T) % Mod) % Mod;
            if (T == 0) break;
        }
        return cache[used][subset] = answer;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        k = sc.nextInt();
        Mod = sc.nextInt();

        if (n % 2 == 1) {
            System.out.println(fastExponentiation(k, n));
            sc.close();
            return;
        }

        fact = new long[n + 1];
        inv_fact = new long[n + 1];
        inv = new long[n + 1];
        cache = new long[19][n + 1];

        fact[0] = inv_fact[0] = 1;
        fact[1] = inv_fact[1] = 1;

        for (int i = 2; i <= n; ++i) {
            fact[i] = (fact[i - 1] * i) % Mod;
            inv[i] = (long) ((Mod - Mod / i) * inv[Mod % i] % Mod);
            inv_fact[i] = (inv_fact[i - 1] * inv[i]) % Mod;
        }

        for (int i = 0; i <= 18; ++i)
            for (int j = 0; j <= n; ++j)
                cache[i][j] = -1;

        long result = (fastExponentiation(k, n) - recursiveSolve(0, n) + Mod) % Mod;
        System.out.println(result);
        sc.close();
    }
}
